window.BFOS_MANUALS = [{"id":"man-i","code":"I","title":"Statuto, Struttura e Governance","org":"Famiglia Button","server":"Gamma RP","version":"1.0","documentStatus":"DA RATIFICARE","nature":"Stabile","effective":"Dopo approvazione della Direzione","revision":"Prima revisione dopo 30 giorni dal wipe; successivamente ogni 90 giorni o quando necessario.","sourceFile":"Manuale_I_Famiglia_Button_Gamma_RP_v1_0.docx","pages":33,"sections":[{"num":"00","title":"CONTROLLO DEL DOCUMENTO","subtitle":"Versione, ambito, stato e regole di utilizzo.","blocks":[{"t":"table","head":["CAMPO","VALORE","STATO"],"rows":[["Organizzazione","Famiglia Button","APPROVATO"],["Server","Gamma RP","APPROVATO"],["Manuale","Manuale I - Statuto, Struttura e Governance","APPROVATO"],["Versione","1.0","APPROVATO"],["Stato","BOZZA DA RATIFICARE","DA RATIFICARE"],["Entrata in vigore","Dopo approvazione della Direzione","DA RATIFICARE"],["Revisione","Prima revisione dopo 30 giorni dal wipe; successivamente ogni 90 giorni o quando necessario.","CONFIGURABILE"]]},{"t":"note","label":"PREVALENZA DEL REGOLAMENTO DEL SERVER","v":"In caso di contrasto tra questo manuale e il regolamento ufficiale del server, prevale sempre il regolamento del server e ogni indicazione ricevuta dallo staff. Le procedure che richiedono autorizzazioni, ticket o verifiche sono sviluppate nel Manuale II."},{"t":"h","n":"0.1","v":"Come utilizzare questo manuale"},{"t":"p","v":"Il Manuale I contiene le regole strutturali dell’organizzazione. Non definisce missioni numeriche, punteggi, obiettivi economici o criteri automatici di promozione: tali elementi saranno trattati nel Manuale III e potranno essere sperimentati senza modificare lo Statuto."}],"states":["APPROVATO","DA RATIFICARE","CONFIGURABILE"]},{"num":"00-B","title":"MAPPA DELLA COLLANA","subtitle":"Il Manuale I definisce la base; gli altri volumi sviluppano le parti variabili.","blocks":[{"t":"cols","cols":[{"title":"Contenuti stabili nel Manuale I","items":["Identità e principi","Gerarchia e ruoli","Accessi e riunioni","Condotta e riservatezza"]},{"title":"Contenuti sviluppati negli altri volumi","items":["Procedure operative - Manuale II","Valutazione e missioni - Manuale III","Streamer e contenuti - Manuale IV","Moduli e registri - Kit operativo"]}]},{"t":"table","head":["VOLUME","FUNZIONE","NATURA"],"rows":[["Manuale I","Struttura e regole di governo","Stabile"],["Manuale II","Procedure e gestione delle risorse","Operativo"],["Manuale III","Progressione, valutazione e missioni","Sperimentale"],["Manuale IV","Streamer, ecosistema e contenuti","Separato"],["Kit operativo","Schede, registri e checklist","Aggiornabile"]]}],"states":["SPERIMENTALE"]},{"num":"00-A","title":"LEGENDA DEGLI STATI","subtitle":"Ogni regola indica chiaramente il proprio livello di approvazione.","blocks":[{"t":"table","head":["STATO","SIGNIFICATO"],"rows":[["APPROVATO","Regola attiva, ratificata o già definita."],["CONFIGURABILE","Parametro modificabile senza riscrivere l’intero manuale."],["DA RATIFICARE","Proposta da discutere e approvare formalmente."],["VERIFICA STAFF","Aspetto subordinato al regolamento o a un’autorizzazione dello staff."],["TEMPORANEO","Accordo valido fino a una data, un evento o una nuova decisione."],["RISERVATO","Informazione accessibile solo ai ruoli autorizzati."]]},{"t":"note","label":"PRINCIPIO DI CHIAREZZA","v":"Nessuna proposta deve essere presentata ai membri come regola definitiva finché non è stata ratificata. Le parti ancora aperte restano visibili e tracciabili."},{"t":"cols","cols":[{"title":"1  Identità della Famiglia","items":["2  Principi organizzativi","3  Struttura generale della Famiglia","4  Direzione","5  Livelli interni","6  Ruoli e responsabilità","7  Aree funzionali","8  Ingresso nella Famiglia","9  Accessi e autorizzazioni"]},{"title":"10  Riunioni e allineamento","items":["11  Comunicazione interna","12  Condotta e disciplina","13  Gestione dei conflitti","14  Riservatezza e sicurezza","15  Relazioni esterne e alleati","16  Sistema documentale","17  Entrata in vigore","A-E  Allegati operativi"]}]}],"states":["APPROVATO","DA RATIFICARE","CONFIGURABILE","VERIFICA STAFF","TEMPORANEO","RISERVATO"]},{"num":"01","title":"IDENTITÀ DELLA FAMIGLIA","subtitle":"Definire chi siamo, come ci presentiamo e quale tipo di gioco vogliamo costruire.","blocks":[{"t":"h","n":"1.1","v":"Denominazione e identità"},{"t":"p","v":"L’organizzazione opera con la denominazione Famiglia Button all’interno di Gamma RP. La denominazione rappresenta un’identità narrativa comune, ma anche un impegno organizzativo: chi ne fa parte contribuisce alla reputazione, alla continuità e alla qualità delle interazioni generate nel server."},{"t":"h","n":"1.2","v":"Scopo generale"},{"t":"p","v":"Lo scopo della Famiglia è costruire un’organizzazione riconoscibile, coordinata e capace di produrre gioco per i propri membri e per le altre realtà del server. Il valore della struttura non si misura soltanto attraverso denaro, forza o risultati immediati, ma attraverso affidabilità, continuità narrativa, relazioni e capacità di trasformare le idee in scene concrete."},{"t":"note","label":"FORMULA IDENTITARIA","v":"Una Famiglia deve essere riconoscibile per metodo, comportamento, qualità delle interazioni e capacità di organizzare gioco; non soltanto per forza numerica o capacità di sparare."},{"t":"h","n":"1.3","v":"Valori fondamentali"},{"t":"cols","cols":[{"title":"Valori interni","items":["Lealtà RP e coerenza del personaggio","Responsabilità verso il gruppo","Chiarezza delle informazioni","Rispetto dei ruoli","Capacità di collaborare"]},{"title":"Valore prodotto nel server","items":["Scene con conseguenze","Interazioni con persone nuove","Collaborazioni tra realtà diverse","Eventi e opportunità","Qualità prima della ripetizione"]}]},{"t":"h","n":"1.4","v":"Obiettivi del wipe"},{"t":"ul","v":["Avviare una struttura leggibile sin dai primi giorni.","Costruire un organico sostenibile fino a 30 giocatori, evitando ingressi indiscriminati.","Distribuire responsabilità concrete e verificabili.","Ridurre dipendenza dal Capo per le attività quotidiane.","Aumentare varietà RP, relazioni e capacità di iniziativa.","Tracciare attività, informazioni e risorse attraverso strumenti condivisi."]},{"t":"h","n":"1.5","v":"Identità pubblica e identità riservata"},{"t":"p","v":"La Famiglia può mantenere una presenza pubblica attraverso eventi, business, collaborazioni e relazioni personali. L’identità pubblica non deve esporre struttura interna, accordi, sedi o informazioni operative. Ciò che viene comunicato alla città deve essere coerente con il personaggio e con gli obiettivi narrativi."},{"t":"h","n":"1.6","v":"Standard di comportamento"},{"t":"ul","v":["Agire in modo coerente con ruolo e livello.","Evitare scene ripetitive quando esistono alternative narrative.","Creare occasioni di gioco anche per persone esterne al gruppo abituale.","Proteggere reputazione e informazioni senza isolarsi dal resto del server."]}],"states":[]},{"num":"02","title":"PRINCIPI ORGANIZZATIVI","subtitle":"Regole fondamentali che orientano tutte le decisioni interne.","blocks":[{"t":"table","head":["PRINCIPIO","APPLICAZIONE"],"rows":[["Unità di comando","Ogni attività deve avere un responsabile riconoscibile. Ordini contraddittori o responsabilità diffuse creano ritardi e conflitti."],["Chiarezza delle responsabilità","Ogni membro deve conoscere ruolo, referente, autonomia e risultato atteso."],["Informazione condivisa","Accordi, modifiche e decisioni rilevanti devono essere comunicati e registrati."],["Tracciabilità","Attività, incassi e risorse comuni devono essere registrati per permettere verifiche e divisioni eque."],["Meritocrazia","La crescita considera affidabilità, competenze, qualità RP e capacità di creare valore, non soltanto presenza o amicizie."],["Compartimentazione","Le informazioni vengono condivise in base al ruolo e alla necessità operativa."],["Esecuzione","Ogni riunione deve produrre responsabili, azioni e scadenze. Un’idea non assegnata resta soltanto una proposta."],["Qualità RP","La ripetizione meccanica non sostituisce la costruzione di gioco, relazioni e conseguenze."]]},{"t":"note","label":"REGOLA DI INTERPRETAZIONE","v":"Quando due principi entrano in tensione, la Direzione sceglie la soluzione che protegge contemporaneamente il regolamento del server, la coerenza RP e la sostenibilità della struttura."}],"states":[]},{"num":"03","title":"STRUTTURA GENERALE DELLA FAMIGLIA","subtitle":"Composizione, perimetro interno ed elementi esterni.","blocks":[{"t":"h","n":"3.1","v":"Organico obiettivo"},{"t":"p","v":"La configurazione iniziale prevede un organico obiettivo di 30 membri. La crescita deve essere progressiva e compatibile con la capacità reale di coordinare persone, informazioni, accessi e attività."},{"t":"table","head":["COMPONENTE","N.","FUNZIONE GENERALE","STATO"],"rows":[["Direzione","4","1 Capo + 3 Vicecapi","APPROVATO"],["Livello 1","5","Élite operativa e comando squadre","CONFIGURABILE"],["Livello 2","6","Coordinamento e formazione","CONFIGURABILE"],["Livello 3","7","Nucleo operativo","CONFIGURABILE"],["Livello 4","5","Affiliati in crescita","DA RATIFICARE"],["Livello 5","3","Aspiranti in prova","DA RATIFICARE"]]},{"t":"h","n":"3.2","v":"Categorie organizzative"},{"t":"ul","v":["Direzione: organo decisionale e di coordinamento.","Membri effettivi: persone integrate nella struttura, con livello e responsabilità definite.","Aspiranti: persone in fase di prova, con accessi limitati e tutor assegnato.","Alleati esterni: collaboratori non appartenenti alla Famiglia, utili per attività o relazioni specifiche.","Contatti: persone o business con cui esiste una relazione, senza obblighi di appartenenza."]},{"t":"note","label":"PRINCIPIO DI CAPACITÀ","v":"La Famiglia non deve raggiungere il numero massimo se non è in grado di garantire coordinamento, accessi controllati, tutoraggio e qualità delle interazioni."},{"t":"h","n":"3.3","v":"Criteri di crescita dell’organico"},{"t":"ul","v":["Aumentare il numero solo quando esistono tutor e referenti disponibili.","Mantenere proporzione tra Direzione, livelli esperti e nuovi ingressi.","Evitare che più aspiranti ricevano informazioni senza un reale percorso di prova.","Rivedere la distribuzione dei livelli quando cambiano presenze e competenze."]},{"t":"h","n":"3.4","v":"Segnali di saturazione"},{"t":"p","v":"Riunioni disordinate, radio non aggiornata, soldi non tracciati, attività sovrapposte e membri senza referente indicano che la struttura sta crescendo più velocemente della propria capacità di governo."}],"states":["APPROVATO","DA RATIFICARE","CONFIGURABILE"]},{"num":"04","title":"DIREZIONE","subtitle":"Autorità, deleghe, continuità e responsabilità decisionale.","blocks":[{"t":"h","n":"4.1","v":"Composizione"},{"t":"p","v":"La Direzione è composta da 1 Capo e 3 Vicecapi. I componenti della Direzione ricoprono un ruolo e non un livello operativo. La loro autorità deriva dalla responsabilità di mantenere coerenza, continuità e capacità di decisione."},{"t":"table","head":["RUOLO","RESPONSABILITÀ","PRODOTTO FINALE ATTESO"],"rows":[["Capo","Definisce strategia, priorità e decisione finale.","Coerenza complessiva e tutela della Famiglia."],["Vicecapo - Operazioni","Coordina attività, squadre e responsabili.","Piani eseguibili, briefing e debriefing."],["Vicecapo - Risorse","Supervisiona tesoreria, mezzi, armi e approvvigionamenti.","Risorse tracciate e disponibili."],["Vicecapo - Persone e relazioni","Supervisiona inserimenti, alleati, comunicazione e clima interno.","Organico affidabile e relazioni sostenibili."]]},{"t":"h","n":"4.2","v":"Regole decisionali"},{"t":"ol","v":["Le decisioni strategiche vengono discusse dalla Direzione.","Il Capo mantiene la decisione finale quando non emerge una posizione condivisa.","Ogni area ha un referente principale e un sostituto.","Le decisioni che modificano accordi, accessi o struttura devono essere registrate.","Una delega non elimina la responsabilità di verifica del delegante."]},{"t":"h","n":"4.3","v":"Vacanza, assenza e sostituzione"},{"t":"p","v":"In caso di assenza prolungata, il ruolo viene coperto temporaneamente attraverso una delega esplicita. L’accesso alla Direzione non costituisce una promozione automatica dal Livello 1: richiede necessità organizzativa, fiducia e valutazione complessiva."}],"states":[]},{"num":"05","title":"LIVELLI INTERNI","subtitle":"Posizionamento, autonomia e aspettative generali.","blocks":[{"t":"note","label":"SEPARAZIONE FONDAMENTALE","v":"La Direzione è un ruolo di governo. I Livelli 1-5 descrivono invece il grado di autonomia, fiducia e competenza dei membri operativi."},{"t":"table","head":["LIVELLO","AUTONOMIA","ASPETTATIVA GENERALE","ACCESSI"],"rows":[["Livello 1","Autonomia elevata","Guida squadre, pianifica attività complesse, forma e valuta.","Accesso ampio su delega."],["Livello 2","Autonomia consolidata","Coordina piccoli gruppi, forma membri e gestisce parti di operazioni.","Accesso funzionale alla propria area."],["Livello 3","Autonomia operativa","Esegue attività, gestisce incarichi semplici e produce debriefing.","Accesso ordinario."],["Livello 4","Autonomia in crescita","Partecipa, apprende procedure e sviluppa una specializzazione.","Accesso limitato e progressivo."],["Livello 5","Periodo di prova","Osserva, collabora con tutor e dimostra affidabilità.","Solo informazioni indispensabili."]]},{"t":"h","n":"5.1","v":"Mobilità tra livelli"},{"t":"p","v":"Il passaggio di livello non è automatico e non dipende soltanto dal tempo trascorso. La promozione richiede valutazione delle competenze, affidabilità, conoscenza delle regole, qualità RP e disponibilità di posti. Missioni, soglie e criteri saranno definiti nel Manuale III e inizialmente sperimentati."},{"t":"cols","cols":[{"title":"Cosa il livello indica","items":["Fiducia","Autonomia","Responsabilità","Accesso alle informazioni"]},{"title":"Cosa il livello non garantisce","items":["Promozione automatica","Ruolo in Direzione","Privilegi senza responsabilità","Immunità da revisioni o retrocessioni"]}]},{"t":"h","n":"5.2","v":"Regole comuni a tutti i livelli"},{"t":"ul","v":["Conoscere il proprio referente e il proprio sostituto.","Rendicontare attività e risorse comuni.","Collaborare con membri di livello diverso.","Accettare revisioni, affiancamenti e cambi di incarico quando necessari."]},{"t":"h","n":"5.3","v":"Specializzazioni"},{"t":"p","v":"Il livello misura autonomia e fiducia; la specializzazione descrive ciò che il membro sa fare. Combattimento, guida, logistica, intelligence, economia, formazione e relazioni esterne possono essere sviluppate in percorsi differenti senza creare gerarchie parallele."}],"states":[]},{"num":"06","title":"RUOLI E RESPONSABILITÀ","subtitle":"Ogni incarico deve produrre un risultato osservabile.","blocks":[{"t":"h","n":"6.1","v":"Principio del prodotto finale atteso"},{"t":"p","v":"Ogni ruolo viene descritto attraverso il valore che deve produrre per la Famiglia. Titolo, anzianità o presenza non sostituiscono il risultato: il membro deve sapere cosa consegnare, a chi risponde e quali informazioni deve registrare."},{"t":"table","head":["CAMPO","DEFINIZIONE"],"rows":[["Ruolo","Nome dell’incarico o area di responsabilità."],["Referente","Persona a cui il ruolo risponde."],["Sostituto","Persona che garantisce continuità in caso di assenza."],["Autonomia","Decisioni che può assumere senza autorizzazione preventiva."],["Risorse","Mezzi, denaro, accessi e strumenti affidati."],["Prodotto finale","Risultato concreto che deve essere disponibile o verificabile."],["Rendicontazione","Informazioni da registrare e frequenza di aggiornamento."]]},{"t":"h","n":"6.2","v":"Obblighi comuni"},{"t":"ul","v":["Conoscere le regole e gli accordi che riguardano il proprio ruolo.","Aggiornare radio, applicativo e registri necessari.","Comunicare tempestivamente problemi, variazioni e risultati.","Collaborare con il sostituto e garantire continuità.","Non utilizzare ruolo, accessi o risorse per interessi personali incompatibili.","Partecipare a briefing e debriefing quando coinvolto."]}],"states":[]},{"num":"07","title":"AREE FUNZIONALI","subtitle":"Distribuire il lavoro per funzioni e non soltanto per persone.","blocks":[{"t":"table","head":["AREA","PRODOTTO FINALE ATTESO"],"rows":[["Direzione e coordinamento","Priorità, decisioni, calendario e allineamento."],["Operazioni","Pianificazione e coordinamento delle attività sul campo."],["Logistica e mezzi","Veicoli, equipaggiamento, trasporti e disponibilità."],["Economia e tesoreria","Registrazione risorse, spese, riserve e rendiconti."],["Intelligence","Raccolta, verifica, classificazione e diffusione delle informazioni."],["Reclutamento e formazione","Ingresso, tutoraggio, verifica e crescita delle persone."],["Relazioni esterne","Alleati, business, altre organizzazioni e contatti."],["Eventi e presenza pubblica","Eventi, reputazione, collaborazioni e sviluppo di nuove scene."],["Applicativo e documentazione","Aggiornamento registri, permessi, versioni e qualità dei dati."],["Media e streamer","Coordinamento con il Manuale IV senza confondere visibilità e grado."]]},{"t":"note","label":"REGOLA DI ASSEGNAZIONE","v":"Ogni area deve avere un responsabile, un sostituto e almeno un risultato periodico verificabile. Un membro può appartenere a più aree, ma non deve ricevere incarichi incompatibili con il tempo disponibile."}],"states":[]},{"num":"08","title":"INGRESSO NELLA FAMIGLIA","subtitle":"Un percorso progressivo basato su comportamento e fiducia.","blocks":[{"t":"h","n":"8.1","v":"Fasi di ingresso"},{"t":"ol","v":["Segnalazione o candidatura.","Primo contatto e verifica della compatibilità RP.","Colloquio iniziale con almeno un responsabile.","Inserimento come aspirante con tutor assegnato.","Periodo di osservazione e partecipazione controllata.","Valutazione finale: conferma, proroga o esclusione."]},{"t":"h","n":"8.2","v":"Criteri osservati"},{"t":"cols","cols":[{"title":"Indicatori positivi","items":["Coerenza RP","Affidabilità","Capacità di ascolto","Comunicazione","Collaborazione"]},{"title":"Indicatori di rischio","items":["Ricerca immediata di accessi","Informazioni contraddittorie","Comportamenti impulsivi","Dipendenza da amicizie OOC","Mancato rispetto delle indicazioni"]}]},{"t":"h","n":"8.3","v":"Limiti durante la prova"},{"t":"ul","v":["Nessun accesso automatico a sedi, civici o proprietà sensibili.","Nessun accesso completo a cassa, magazzini e accordi riservati.","Partecipazione alle attività in presenza di un referente.","Conoscenza limitata alle informazioni necessarie.","Nessuna rappresentanza esterna senza delega."]},{"t":"note","label":"PRINCIPIO DI FIDUCIA PROGRESSIVA","v":"La fiducia non viene concessa in blocco al momento dell’ingresso. Si costruisce attraverso comportamento, continuità e responsabilità dimostrate nel tempo."},{"t":"h","n":"8.4","v":"Esito del periodo di prova"},{"t":"p","v":"Al termine del periodo il tutor presenta una valutazione sintetica. La Direzione può confermare l’ingresso, prorogare la prova con obiettivi chiari oppure interrompere il percorso. L’esito deve essere comunicato direttamente e registrato."},{"t":"h","n":"8.5","v":"Consegna progressiva degli accessi"},{"t":"p","v":"La conferma come membro effettivo non implica l’accesso immediato a ogni risorsa. Sedi, applicativo, cassa, magazzini e informazioni riservate vengono assegnati in base al ruolo reale."}],"states":[]},{"num":"09","title":"ACCESSI E AUTORIZZAZIONI","subtitle":"Compartimentare informazioni, luoghi e risorse in base al ruolo.","blocks":[{"t":"h","n":"9.1","v":"Principio del minimo accesso necessario"},{"t":"p","v":"Ogni membro riceve esclusivamente gli accessi necessari per svolgere il proprio ruolo. L’anzianità non genera automaticamente accesso a tutte le informazioni. Gli accessi devono poter essere assegnati, verificati e revocati."},{"t":"table","head":["CLASSE","ACCESSO","ESEMPI"],"rows":[["Informazioni pubbliche","Tutti","Identità pubblica, eventi e contatti non sensibili."],["Informazioni interne","Membri effettivi","Organizzazione, calendario e attività ordinarie."],["Informazioni operative","Partecipanti e responsabili","Dettagli necessari per singole attività."],["Informazioni riservate","Direzione e ruoli autorizzati","Accordi, sedi, fornitori, risorse e strategie."],["Informazioni temporanee","Gruppo definito","Accesso valido fino alla conclusione dell’attività."]]},{"t":"h","n":"9.2","v":"Revoca e uscita"},{"t":"ol","v":["Sospendere gli accessi non più necessari.","Recuperare chiavi, mezzi, risorse o credenziali assegnate.","Aggiornare radio, applicativo e registri.","Comunicare ai referenti interessati la modifica.","Registrare motivazione e data della revoca."]}],"states":[]},{"num":"10","title":"RIUNIONI, BRIEFING E ALLINEAMENTO","subtitle":"Creare una cadenza stabile senza trasformare il gioco in burocrazia.","blocks":[{"t":"table","head":["INCONTRO","FREQUENZA","OUTPUT MINIMO"],"rows":[["Riunione post Cartello","Dopo ogni incontro rilevante","Accordi, modifiche, condizioni e responsabili."],["Riunione di metà settimana","Una volta a settimana","Azioni svolte, problemi, risorse e priorità."],["Riunione Direzione","Quando necessario","Decisioni strategiche, persone e accessi."],["Briefing operativo","Prima di attività complesse","Obiettivo, ruoli, mezzi, rischi e piano alternativo."],["Debriefing","Dopo attività rilevanti","Risultati, informazioni, errori e sviluppi."]]},{"t":"h","n":"10.1","v":"Regole per ogni riunione"},{"t":"ul","v":["Ordine del giorno comunicato prima dell’incontro quando possibile.","Un facilitatore mantiene il confronto sul tema.","Le decisioni vengono distinte dalle proposte.","Ogni decisione assegna responsabile e scadenza.","Gli assenti ricevono un riepilogo attraverso l’applicativo.","Le informazioni riservate vengono condivise soltanto con gli autorizzati."]},{"t":"note","label":"REGOLA DI CHIUSURA","v":"Una riunione si considera conclusa solo quando è chiaro cosa deve essere fatto, da chi, entro quando e dove verrà registrato il risultato."}],"states":[]},{"num":"11","title":"COMUNICAZIONE INTERNA","subtitle":"Radio, applicativo e aggiornamenti come responsabilità operative.","blocks":[{"t":"h","n":"11.1","v":"Canali ufficiali"},{"t":"table","head":["CANALE","USO PRINCIPALE"],"rows":[["Radio","Coordinamento rapido in gioco e stato operativo."],["Applicativo","Decisioni, attività, soldi, accordi e storico."],["Discord / canali OOC","Organizzazione tecnica, disponibilità e supporto."],["Riunione RP","Decisioni, chiarimenti e allineamento del personaggio."]]},{"t":"h","n":"11.2","v":"Obblighi di aggiornamento"},{"t":"ul","v":["La radio deve essere impostata e aggiornata secondo le indicazioni correnti.","Le informazioni rilevanti non devono rimanere nella memoria di una sola persona.","Chi partecipa a un incontro esterno è responsabile del debriefing.","Attività, incassi e risorse comuni devono essere registrati.","Un’informazione non verificata deve essere indicata come tale.","I cambiamenti temporanei devono riportare scadenza o condizione di cessazione."]},{"t":"note","label":"PRINCIPIO DI RENDICONTAZIONE","v":"Un’attività non comunicata non può essere valutata, coordinata o utilizzata correttamente nelle decisioni della Famiglia."}],"states":[]},{"num":"12","title":"CONDOTTA INTERNA E DISCIPLINA","subtitle":"Coerenza, rispetto e responsabilità come standard minimi.","blocks":[{"t":"table","head":["AMBITO","STANDARD ATTESO"],"rows":[["Gerarchia","Rispettare ruoli e catena di comando nelle interazioni RP."],["Dissenso","Esporre dubbi e alternative nei momenti e canali appropriati."],["Affidabilità","Mantenere impegni o comunicare per tempo l’impossibilità."],["Separazione RP/OOC","Non usare amicizie esterne per alterare decisioni del personaggio."],["Risorse comuni","Non utilizzare soldi, mezzi o informazioni senza autorizzazione."],["Reputazione","Evitare comportamenti pubblici incoerenti con l’identità della Famiglia."],["Collaborazione","Non ostacolare attività comuni per preferenze personali non dichiarate."]]},{"t":"h","n":"12.1","v":"Comportamenti incompatibili"},{"t":"ul","v":["Diffusione non autorizzata di informazioni riservate.","Mancata rendicontazione ripetuta di attività o denaro comune.","Uso del ruolo per favorire amici o interessi personali incompatibili.","Contraddizione pubblica deliberata di decisioni interne senza confronto.","Comportamenti che generano conflitti evitabili con staff o altre realtà.","Abbandono sistematico delle responsabilità assegnate."]}],"states":[]},{"num":"13","title":"GESTIONE DEI CONFLITTI","subtitle":"Affrontare problemi e violazioni con un processo progressivo e verificabile.","blocks":[{"t":"h","n":"13.1","v":"Procedura"},{"t":"ol","v":["Segnalazione del problema con fatti, contesto e persone coinvolte.","Raccolta delle versioni senza discussioni pubbliche disordinate.","Chiarimento o mediazione quando possibile.","Valutazione del responsabile o della Direzione.","Decisione, azione correttiva e registrazione dell’esito.","Verifica successiva quando prevista."]},{"t":"table","head":["LIVELLO","MISURA","APPLICAZIONE"],"rows":[["1","Richiamo e chiarimento","Errore occasionale o incomprensione."],["2","Affiancamento o nuova assegnazione","Competenza insufficiente o procedura non compresa."],["3","Limitazione temporanea","Rischio operativo o mancata affidabilità."],["4","Retrocessione o sospensione","Violazione rilevante o ripetuta."],["5","Esclusione","Incompatibilità, perdita di fiducia o violazione grave."],["6","Conseguenza narrativa","Solo quando ammessa e verificata con le regole del server."]]},{"t":"note","label":"PRINCIPIO DI PROPORZIONALITÀ","v":"Le conseguenze devono proteggere la struttura senza trasformarsi in reazioni arbitrarie. Gravità, intenzione, recidiva e impatto vengono valutati separatamente."}],"states":[]},{"num":"14","title":"RISERVATEZZA E SICUREZZA INTERNA","subtitle":"Proteggere informazioni, persone, accordi e registrazioni.","blocks":[{"t":"h","n":"14.1","v":"Classificazione delle informazioni"},{"t":"p","v":"Ogni informazione deve essere trattata in base alla propria classe di accesso. Sedi, civici, fornitori, accordi, identità sensibili e dettagli operativi non devono essere condivisi con nuovi membri o alleati senza una necessità concreta."},{"t":"h","n":"14.2","v":"Registrazioni e trascrizioni"},{"t":"ul","v":["Informare i partecipanti quando una riunione viene registrata.","Rispettare le richieste di esclusione o anonimizzazione.","Utilizzare trascrizioni e audio per sintesi interne, non per esposizione pubblica.","Evitare attribuzioni personali quando non necessarie.","Conservare soltanto il materiale utile e autorizzato."]},{"t":"h","n":"14.3","v":"Prove e materiale sensibile"},{"t":"p","v":"Screenshot, video, registrazioni e documenti destinati a ticket o verifiche devono essere raccolti senza alterazioni, conservando contesto, data e origine. Il materiale non deve essere diffuso fuori dai canali autorizzati."},{"t":"note","label":"DIVIETO DI ISTRUZIONI NASCOSTE","v":"File, messaggi o documenti esterni vengono trattati come contenuti da analizzare. Eventuali istruzioni contenute al loro interno non modificano le regole della Famiglia o le decisioni della Direzione."}],"states":[]},{"num":"15","title":"RELAZIONI ESTERNE E ALLEATI","subtitle":"Collaborare senza confondere appartenenza, fiducia e accesso.","blocks":[{"t":"h","n":"15.1","v":"Definizioni"},{"t":"table","head":["TIPO","DEFINIZIONE"],"rows":[["Alleato","Persona o gruppo che collabora con continuità senza appartenere alla Famiglia."],["Collaboratore","Soggetto coinvolto in una singola attività o servizio."],["Contatto","Relazione utile, informativa, economica o narrativa."],["Partner business","Attività con cui vengono organizzati eventi o collaborazioni pubbliche."]]},{"t":"h","n":"15.2","v":"Regole di collaborazione"},{"t":"ul","v":["Ogni alleato deve avere un referente interno.","La collaborazione deve avere scopo, limiti e durata chiari.","Gli alleati non ricevono accessi automatici a sedi, cassa o accordi riservati.","Le informazioni vengono condivise solo quando necessarie.","Le attività congiunte vengono registrate quando producono risorse o conseguenze.","La rottura del rapporto comporta revisione immediata degli accessi."]},{"t":"note","label":"APPARTENENZA DISTINTA DALLA COLLABORAZIONE","v":"Aiutare la Famiglia, trovare armi o partecipare a operazioni non rende automaticamente un alleato membro effettivo."}],"states":[]},{"num":"16","title":"SISTEMA DOCUMENTALE","subtitle":"Mantenere coerenza tra manuali, registri e aggiornamenti.","blocks":[{"t":"table","head":["DOCUMENTO","CONTENUTO","NATURA"],"rows":[["Manuale I","Statuto, struttura e governance","Stabile"],["Manuale II","Procedure operative e risorse","Operativo"],["Manuale III","Progressione, competenze e missioni","Sperimentale"],["Manuale IV","Streamer, ecosistema e contenuti","Separato"],["Kit operativo","Moduli, registri e checklist","Aggiornabile"]]},{"t":"h","n":"16.1","v":"Processo di modifica"},{"t":"ol","v":["Presentare la proposta indicando problema, modifica e impatto.","Classificare la modifica come strutturale, operativa o parametrica.","Discutere con i ruoli coinvolti.","Ratificare la decisione quando richiesto.","Aggiornare versione, data e registro modifiche.","Comunicare la variazione ai destinatari interessati."]},{"t":"h","n":"16.2","v":"Versioning"},{"t":"p","v":"Le modifiche sostanziali aumentano la versione principale; le correzioni e gli aggiornamenti minori aumentano la versione secondaria. Le versioni precedenti vengono archiviate e non cancellate, così da mantenere la cronologia delle decisioni."}],"states":["SPERIMENTALE"]},{"num":"17","title":"ENTRATA IN VIGORE E ATTUAZIONE","subtitle":"Passare dal documento alla pratica con un piano semplice.","blocks":[{"t":"h","n":"17.1","v":"Condizioni per l’entrata in vigore"},{"t":"ul","v":["Approvazione dell’indice e dei principi fondamentali.","Nomina dei responsabili delle aree principali.","Condivisione del manuale con tutti i membri effettivi.","Configurazione iniziale di radio, applicativo e registri.","Definizione del calendario delle riunioni.","Registrazione delle parti ancora da ratificare."]},{"t":"h","n":"17.2","v":"Piano di avvio in sette giorni"},{"t":"table","head":["TEMPO","AZIONE"],"rows":[["Giorno 1","Ratifica struttura e direzione."],["Giorno 2","Assegnazione aree, ruoli e sostituti."],["Giorno 3","Revisione accessi, radio e applicativo."],["Giorno 4","Registrazione accordi e risorse esistenti."],["Giorno 5","Briefing generale con domande e chiarimenti."],["Giorno 6","Prima attività applicando briefing e debriefing."],["Giorno 7","Recap, problemi emersi e azioni correttive."]]},{"t":"note","label":"CRITERIO DI SUCCESSO","v":"Il manuale funziona quando i membri sanno chi decide, cosa devono produrre, dove trovare le informazioni e come comunicare i risultati senza dipendere costantemente dalla presenza del Capo."},{"t":"h","n":"17.3","v":"Verifica del primo mese"},{"t":"table","head":["AREA","DOMANDA DI VERIFICA"],"rows":[["Gerarchia","Tutti sanno a chi rispondono?"],["Ruoli","Ogni incarico produce un risultato osservabile?"],["Comunicazione","Radio e applicativo vengono aggiornati?"],["Risorse","Incassi, spese e accessi sono tracciati?"],["Persone","Aspiranti e membri hanno tutor o referente?"],["Qualità RP","Sono aumentate varietà e nuove interazioni?"]]}],"states":[]},{"num":"A","title":"ALLEGATO A - ORGANIGRAMMA","subtitle":"Schema sintetico da personalizzare e aggiornare.","blocks":[{"t":"table","head":["LIVELLO","NOME / RUOLO","REFERENTE","SOSTITUTO","STATO"],"rows":[["Direzione","[CAPO]","-","[SOSTITUTO]","DA RATIFICARE"],["Direzione","[VICECAPO 1]","[CAPO]","[SOSTITUTO]","DA RATIFICARE"],["Direzione","[VICECAPO 2]","[CAPO]","[SOSTITUTO]","DA RATIFICARE"],["Direzione","[VICECAPO 3]","[CAPO]","[SOSTITUTO]","DA RATIFICARE"],["Livello 1","[MEMBRI]","[REFERENTE]","[SOSTITUTO]","CONFIGURABILE"],["Livello 2","[MEMBRI]","[REFERENTE]","[SOSTITUTO]","CONFIGURABILE"],["Livello 3","[MEMBRI]","[REFERENTE]","[SOSTITUTO]","CONFIGURABILE"],["Livello 4","[MEMBRI]","[REFERENTE]","[SOSTITUTO]","CONFIGURABILE"],["Livello 5","[ASPIRANTI]","[TUTOR]","-","CONFIGURABILE"]]}],"states":["DA RATIFICARE","CONFIGURABILE"]},{"num":"B","title":"ALLEGATO B - MATRICE RUOLI","subtitle":"Responsabilità, autonomia e prodotto finale atteso.","blocks":[{"t":"table","head":["RUOLO","REFERENTE","AUTONOMIA","PRODOTTO FINALE","FREQUENZA"],"rows":[["[RUOLO 1]","[NOME]","[DECISIONI CONSENTITE]","[RISULTATO]","[PERIODO]"],["[RUOLO 2]","[NOME]","[DECISIONI CONSENTITE]","[RISULTATO]","[PERIODO]"],["[RUOLO 3]","[NOME]","[DECISIONI CONSENTITE]","[RISULTATO]","[PERIODO]"],["[RUOLO 4]","[NOME]","[DECISIONI CONSENTITE]","[RISULTATO]","[PERIODO]"],["[RUOLO 5]","[NOME]","[DECISIONI CONSENTITE]","[RISULTATO]","[PERIODO]"]]},{"t":"note","label":"ISTRUZIONE DI COMPILAZIONE","v":"Non limitarsi a indicare il titolo. Il prodotto finale deve descrivere cosa deve esistere o essere verificabile quando il ruolo viene svolto correttamente."}],"states":[]},{"num":"C","title":"ALLEGATO C - MATRICE ACCESSI","subtitle":"Assegnazione e revoca delle autorizzazioni.","blocks":[{"t":"table","head":["RISORSA","DIREZIONE","L1","L2-L3","L4","L5"],"rows":[["Sedi ordinarie","Sì","Sì","Sì","Limitato","No"],["Sedi riservate","Sì","Su delega","No","No","No"],["Cassa e tesoreria","Sì","Per ruolo","No","No","No"],["Accordi Cartello","Sì","Su necessità","No","No","No"],["Applicativo - lettura","Sì","Sì","Sì","Limitato","Limitato"],["Applicativo - modifica","Sì","Per area","Proprie attività","Proprie attività","Tutor"],["Magazzino","Sì","Per ruolo","Su autorizzazione","No","No"]]},{"t":"p","v":"La tabella rappresenta una configurazione iniziale e deve essere adattata ai ruoli reali. Ogni eccezione temporanea deve riportare responsabile e data di scadenza."}],"states":[]},{"num":"D","title":"ALLEGATO D - RIUNIONI E VERBALI","subtitle":"Modello sintetico per decisioni, responsabili e scadenze.","blocks":[{"t":"table","head":["CAMPO","CONTENUTO"],"rows":[["Data e orario","[DATA - ORA]"],["Tipo di riunione","[DIREZIONE / GENERALE / POST CARTELLO / DEBRIEF]"],["Partecipanti","[NOMI]"],["Assenti da aggiornare","[NOMI]"],["Argomenti","[ELENCO]"],["Decisioni","[DECISIONI RATIFICATE]"],["Proposte aperte","[PROPOSTE DA RATIFICARE]"],["Responsabili","[AZIONE - RESPONSABILE - SCADENZA]"],["Informazioni riservate","[DESTINATARI]"],["Prossima verifica","[DATA / CONDIZIONE]"]]}],"states":["DA RATIFICARE"]},{"num":"E","title":"ALLEGATO E - SCHEDA INGRESSO","subtitle":"Raccogliere informazioni e valutazioni senza ingressi improvvisati.","blocks":[{"t":"table","head":["CAMPO","VALORE"],"rows":[["Nome personaggio","[NOME]"],["ID / contatto","[ID]"],["Data primo contatto","[DATA]"],["Segnalato da","[NOME]"],["Esperienza RP","[SINTESI]"],["Motivazione di ingresso","[MOTIVAZIONE]"],["Punti di forza osservati","[NOTE]"],["Rischi o dubbi","[NOTE]"],["Tutor assegnato","[NOME]"],["Accessi iniziali","[ELENCO]"],["Durata prova","[PERIODO]"],["Esito","[CONFERMATO / PROROGA / ESCLUSO]"]]}],"states":[]},{"num":"R","title":"RATIFICA E REGISTRO MODIFICHE","subtitle":"Firma, approvazione e tracciabilità delle versioni.","blocks":[{"t":"h","n":"R.1","v":"Ratifica"},{"t":"table","head":["RUOLO","NOME","DATA","FIRMA / CONFERMA"],"rows":[["Capo","[NOME]","[DATA]","[CONFERMA]"],["Vicecapo","[NOME]","[DATA]","[CONFERMA]"],["Vicecapo","[NOME]","[DATA]","[CONFERMA]"],["Vicecapo","[NOME]","[DATA]","[CONFERMA]"]]},{"t":"h","n":"R.2","v":"Registro modifiche"},{"t":"table","head":["VERSIONE","DATA","MODIFICA","APPROVATA DA"],"rows":[["1.0","[DATA]","Prima emissione del Manuale I.","[DIREZIONE]"]]},{"t":"note","label":"CHIUSURA","v":"La versione approvata deve essere comunicata ai membri e archiviata. Le copie precedenti restano disponibili come storico, ma non sono più operative."}],"states":[]}]},{"id":"man-ii","code":"II","title":"Procedure Operative e Risorse","org":"Famiglia Button","server":"Gamma RP","version":"1.0","documentStatus":"DA RATIFICARE","nature":"Operativo","effective":"Dopo approvazione della Direzione","revision":"Dopo ogni wipe, modifica del server o variazione degli accordi","sourceFile":"Manuale_II_Famiglia_Button_Gamma_RP_v1_0.docx","pages":32,"sections":[{"num":"00","title":"CONTROLLO DEL DOCUMENTO","subtitle":"Versione, ambito, stato e regole di utilizzo.","blocks":[{"t":"table","head":["CAMPO","VALORE","STATO"],"rows":[["Organizzazione","Famiglia Button","APPROVATO"],["Server","Gamma RP","APPROVATO"],["Manuale","Manuale II - Procedure Operative e Risorse","APPROVATO"],["Versione","1.0","APPROVATO"],["Stato","BOZZA DA RATIFICARE","DA RATIFICARE"],["Entrata in vigore","Dopo approvazione della Direzione","DA RATIFICARE"],["Revisione","Dopo ogni wipe, modifica del server o variazione degli accordi","CONFIGURABILE"]]},{"t":"note","label":"PREVALENZA DEL REGOLAMENTO DEL SERVER","v":"Qualunque procedura descritta nel manuale è subordinata al regolamento ufficiale del server, alle indicazioni dello staff e alle autorizzazioni ottenute tramite ticket."},{"t":"h","n":"0.1","v":"Come utilizzare questo manuale"},{"t":"p","v":"Il Manuale II definisce il metodo con cui le attività vengono preparate, autorizzate, eseguite e registrate. Non assegna punteggi ai membri e non stabilisce criteri automatici di promozione: tali elementi appartengono al Manuale III."}],"states":["APPROVATO","DA RATIFICARE","CONFIGURABILE"]},{"num":"00-B","title":"MAPPA DEL MANUALE","subtitle":"Procedure stabili, parametri aggiornabili e registri operativi.","blocks":[{"t":"table","head":["BLOCCO","CONTENUTO","NATURA"],"rows":[["Governance operativa","Responsabili, ciclo delle attività, briefing e debriefing","OPERATIVO"],["Comunicazione e applicativo","Radio, registrazioni, informazioni e aggiornamenti obbligatori","OPERATIVO"],["Accordi ed economia","Cartello, conto terzi, tesoreria, distribuzioni e reinvestimenti","CONFIGURABILE"],["Azioni sensibili","Rapine, ticket, rapimenti, interrogatori e campi","VERIFICA STAFF"],["Allegati","Schede, registri, cataloghi e checklist sostituibili","CONFIGURABILE"]]},{"t":"note","label":"PRINCIPIO DI STABILITÀ","v":"Il metodo resta nel manuale. Prezzi, soglie, limiti, cooldown, commissioni e cataloghi vengono mantenuti negli allegati o nell’applicativo, così possono essere aggiornati senza riscrivere l’intero volume."}],"states":["CONFIGURABILE","VERIFICA STAFF","OPERATIVO"]},{"num":"01","title":"SCOPO E PRINCIPI OPERATIVI","subtitle":"Dal “cosa fare” al “come farlo in modo coordinato”.","blocks":[{"t":"h","n":"1.1","v":"Obiettivo del Manuale II"},{"t":"p","v":"Il manuale trasforma le decisioni della Direzione in procedure eseguibili. Ogni attività deve avere un responsabile, un obiettivo, partecipanti identificati, risorse assegnate, eventuali autorizzazioni, un esito e una registrazione finale."},{"t":"h","n":"1.2","v":"Principi obbligatori"},{"t":"ul","v":["Nessuna attività sensibile parte senza un responsabile riconoscibile.","Le informazioni rilevanti devono essere condivise e registrate.","Gli incassi della Famiglia devono restare tracciabili.","Il regolamento del server prevale su qualunque accordo interno.","La qualità della scena e le conseguenze RP contano quanto il risultato economico.","Il fallimento operativo non annulla il valore di una scena ben costruita."]},{"t":"note","label":"OUTPUT ATTESO","v":"Ogni membro deve poter capire chi coordina, cosa si sta cercando di ottenere, quali limiti esistono e dove registrare il risultato."}],"states":[]},{"num":"02","title":"CICLO STANDARD DELLE ATTIVITÀ","subtitle":"Una sequenza unica per operazioni semplici e complesse.","blocks":[{"t":"table","head":["FASE","DOMANDA GUIDA","OUTPUT"],"rows":[["1. Proposta","Perché questa attività è utile?","Obiettivo iniziale"],["2. Verifica","È consentita? Serve un ticket?","Vincoli e autorizzazioni"],["3. Pianificazione","Chi fa cosa, con quali mezzi e tempi?","Piano operativo"],["4. Briefing","Tutti conoscono ruoli e condizioni di chiusura?","Squadra allineata"],["5. Esecuzione","La scena resta coerente e controllata?","Azione svolta"],["6. Debriefing","Cosa ha funzionato e cosa no?","Lezioni e sviluppi"],["7. Registrazione","Incassi, partecipanti e conseguenze sono tracciati?","Chiusura documentale"]]},{"t":"h","n":"2.1","v":"Responsabile unico"},{"t":"p","v":"Ogni operazione deve avere un coordinatore. Il responsabile può delegare parti dell’attività, ma resta il punto di riferimento per decisioni, comunicazioni e chiusura del report."}],"states":[]},{"num":"03","title":"CLASSIFICAZIONE DELLE ATTIVITÀ","subtitle":"La complessità determina il livello di preparazione richiesto.","blocks":[{"t":"table","head":["CATEGORIA","ESEMPI","REQUISITI"],"rows":[["Ordinaria","Logistica, trasporto, raccolta, supporto","Responsabile e registrazione essenziale"],["Economica","Vendita, pulizia, servizio conto terzi","Tracciabilità completa e verifica importi"],["Collettiva","Campi, eventi, attività multi-squadra","Calendario, ruoli e briefing"],["Sensibile","Rapimento, interrogatorio, accesso a dati","Motivazione RP e verifica staff"],["Complessa","Rapina strutturata, mezzi speciali","Piano, ticket, prove e piano alternativo"],["Riservata","Cartello, accordi strategici, operazioni interne","Accesso limitato e debrief controllato"]]},{"t":"note","label":"REGOLA DI ESCALATION","v":"Se durante la preparazione aumenta il rischio, cambia il bersaglio o compaiono elementi non previsti, l’attività deve essere riclassificata prima dell’esecuzione."}],"states":[]},{"num":"04","title":"COMUNICAZIONE OPERATIVA E RADIO","subtitle":"La radio è uno strumento di coordinamento, non un archivio.","blocks":[{"t":"h","n":"4.1","v":"Disciplina radio"},{"t":"ul","v":["Aggiornare lo stato quando si entra o si esce da un’attività.","Usare messaggi brevi, chiari e orientati all’azione.","Evitare sovrapposizioni, discussioni e informazioni non necessarie durante le fasi critiche.","Confermare ordini, cambi di piano e richieste di supporto.","Segnalare immediatamente problemi tecnici o violazioni sospette."]},{"t":"h","n":"4.2","v":"Obbligo di aggiornamento"},{"t":"p","v":"La radio non sostituisce l’applicativo. Gli accordi, gli incassi, le decisioni e le informazioni utili oltre la singola scena devono essere registrati nel sistema ufficiale."},{"t":"note","label":"PROBLEMA DA ELIMINARE","v":"Radio ignorata, stato non aggiornato per giorni, attività conosciute soltanto da chi era presente e denaro non collegato a un’operazione."}],"states":[]},{"num":"05","title":"APPLICATIVO UFFICIALE","subtitle":"La registrazione è parte dell’attività, non un compito opzionale.","blocks":[{"t":"table","head":["AREA","DATI MINIMI","RESPONSABILE"],"rows":[["Attività","Titolo, obiettivo, stato, responsabile, partecipanti","Coordinatore"],["Economia","Entrate, uscite, provenienza, destinazione","Tesoriere / delegato"],["Accordi","Controparti, condizioni, data, scadenza","Rappresentante"],["Risorse","Armi, mezzi, materiali, consegne e perdite","Magazzino / logistica"],["Debrief","Esito, problemi, sviluppi e azioni correttive","Responsabile attività"]]},{"t":"h","n":"5.1","v":"Qualità del dato"},{"t":"p","v":"Un’attività non registrata non può essere valutata correttamente, non può essere collegata agli incassi e non può produrre una distribuzione equa. Le correzioni devono conservare traccia della modifica e del responsabile."},{"t":"note","label":"PREROGATIVA","v":"L’utilizzo dell’applicativo è obbligatorio per tutte le attività che coinvolgono risorse, accordi, denaro, informazioni sensibili o più membri della Famiglia."}],"states":[]},{"num":"06","title":"GESTIONE DELLE INFORMAZIONI","subtitle":"Raccogliere, verificare, classificare e distribuire.","blocks":[{"t":"table","head":["LIVELLO","DESCRIZIONE","DIFFUSIONE"],"rows":[["Pubblica","Informazioni già note alla città","Libera"],["Interna","Informazioni utili alla Famiglia","Membri autorizzati"],["Riservata","Accordi, civici, piani e contatti sensibili","Solo ruoli necessari"],["Direzione","Strategia, decisioni e fonti delicate","Direzione"]]},{"t":"h","n":"6.1","v":"Validazione della fonte"},{"t":"ul","v":["Indicare come l’informazione è stata ottenuta in RP.","Distinguere fatti, ipotesi e voci.","Conservare prove quando sono necessarie per ticket o conseguenze.","Non utilizzare informazioni ottenute OOC o tramite stream.","Aggiornare o smentire le informazioni superate."]}],"states":[]},{"num":"07","title":"ACCORDI E REGOLAMENTI","subtitle":"Ogni condizione deve avere data, responsabile e stato.","blocks":[{"t":"table","head":["TIPO","CONTENUTO","GESTIONE"],"rows":[["Permanente","Regola senza scadenza nota","Revisione periodica"],["Temporaneo","Condizione valida fino a una data o evento","Scadenza obbligatoria"],["Riservato","Accordo accessibile a pochi ruoli","Accesso controllato"],["Sperimentale","Prova limitata prima della ratifica","Metriche e revisione"]]},{"t":"h","n":"7.1","v":"Campi obbligatori del registro accordi"},{"t":"ul","v":["Controparti","Condizioni economiche","Quantità e soglie","Data di entrata in vigore","Durata o scadenza","Responsabile interno","Persone informate","Ultima verifica"]}],"states":["SPERIMENTALE"]},{"num":"08","title":"RAPPORTI CON IL CARTELLO","subtitle":"Accesso, consegne, cambio e aggiornamento degli accordi.","blocks":[{"t":"table","head":["CONDIZIONE","VALORE ATTUALE","STATO"],"rows":[["Accesso al dialogo","Consegna iniziale di 1.000 dosi di Fentanyl","TEMPORANEO"],["Cambio ordinario","60/40 a favore del Cartello","TEMPORANEO"],["Soglia vantaggiosa","A 5.000 unità: 60/40 a favore della Famiglia","TEMPORANEO"],["Verifica","Aggiornamento obbligatorio dopo ogni incontro","OPERATIVO"]]},{"t":"note","label":"INTERPRETAZIONE OPERATIVA","v":"Nel cambio ordinario il Cartello trattiene il 60% e la Famiglia riceve il 40%. Al raggiungimento della soglia concordata di 5.000 unità, la proporzione si inverte a favore della Famiglia."},{"t":"h","n":"8.1","v":"Procedura post incontro"},{"t":"ul","v":["Il rappresentante convoca il debriefing.","Le condizioni vengono lette senza dare nulla per scontato.","L’applicativo viene aggiornato con data e responsabile.","Le vecchie condizioni vengono archiviate, non sovrascritte senza traccia.","Le persone non autorizzate ricevono soltanto le informazioni necessarie."]}],"states":["TEMPORANEO","OPERATIVO"]},{"num":"09","title":"SERVIZIO FAZIONI E CONTO TERZI","subtitle":"Gestire clienti esterni senza perdere controllo e tracciabilità.","blocks":[{"t":"table","head":["FASE","CONTROLLO","REGISTRAZIONE"],"rows":[["Richiesta","Identità, provenienza e finalità","Cliente e referente"],["Valutazione","Rischio, quantità e disponibilità","Esito e condizioni"],["Accordo","Commissione, tempi e responsabilità","Percentuali e scadenza"],["Esecuzione","Consegna e verifica importi","Movimenti economici"],["Chiusura","Contestazioni e saldo","Esito finale"]]},{"t":"note","label":"COMMISSIONE","v":"La commissione del servizio conto terzi deve essere ratificata e può variare in base a quantità, rischio, cliente e condizioni del Cartello. Qualunque intervallo precedente resta un riferimento storico finché non viene confermato."},{"t":"h","n":"9.1","v":"Limiti"},{"t":"ul","v":["Nessun servizio senza referente interno","Nessuna consegna priva di registro","Nessuna promessa su condizioni non confermate","Sospensione immediata in caso di rischio per la Famiglia"]}],"states":[]},{"num":"10","title":"TESORERIA E TRACCIABILITÀ","subtitle":"Il denaro della Famiglia deve avere origine, destinazione e responsabile.","blocks":[{"t":"table","head":["MOVIMENTO","DATI OBBLIGATORI","CONTROLLO"],"rows":[["Entrata","Operazione, importo, partecipanti, consegnatario","Verifica del responsabile"],["Uscita","Motivo, beneficiario, approvatore, ricevuta/nota","Doppia conferma se rilevante"],["Reinvestimento","Categoria, importo, risultato atteso","Rendiconto successivo"],["Distribuzione","Criterio, quote, persone pagate","Registro firmato/validato"],["Differenza","Importo mancante o eccedente","Segnalazione immediata"]]},{"t":"h","n":"10.1","v":"Patrimonio collettivo"},{"t":"p","v":"Il denaro sporco generato nelle attività della Famiglia viene considerato risorsa collettiva fino alla registrazione, al reinvestimento e alla distribuzione autorizzata. Il possesso temporaneo non coincide con la proprietà personale."}],"states":[]},{"num":"11","title":"REINVESTIMENTI E DISTRIBUZIONI","subtitle":"Separare riserva, costi operativi e quote personali.","blocks":[{"t":"table","head":["COMPONENTE","FUNZIONE","PARAMETRO"],"rows":[["Riserva","Copertura imprevisti e continuità","CONFIGURABILE"],["Reinvestimento","Armi, mezzi, materiali e operazioni","CONFIGURABILE"],["Quota comune","Sostegno collettivo","CONFIGURABILE"],["Premio operativo","Riconoscimento del contributo","DA RATIFICARE"]]},{"t":"p","v":"Il metodo di distribuzione deve essere definito nel sistema di valutazione e ratificato separatamente. Fino a quel momento, il manuale richiede soltanto trasparenza, registrazione e approvazione della Direzione."},{"t":"note","label":"PRINCIPIO DI EQUITÀ","v":"Trattare allo stesso modo contributi molto diversi può generare demotivazione; premiare soltanto il denaro prodotto può penalizzare logistica, formazione, intelligence e qualità RP."}],"states":["DA RATIFICARE","CONFIGURABILE"]},{"num":"12","title":"CATALOGO DELLE RAPINE","subtitle":"Accessibilità, condizioni, rischio e incasso medio.","blocks":[{"t":"table","head":["CAMPO","DESCRIZIONE","GESTIONE"],"rows":[["Nome attività","Identificazione univoca","Catalogo applicativo"],["Livello di accesso","Chi può proporla o guidarla","CONFIGURABILE"],["Partecipanti","Minimo e massimo","Regolamento server"],["Requisiti","Mezzi, strumenti, investimento","Aggiornabile"],["Incasso medio","Intervallo realistico, non promessa","Aggiornabile"],["Rischio","Polizia, arresto, perdita risorse","Valutazione interna"],["Cooldown","Limiti tecnici o organizzativi","Regolamento server"]]},{"t":"h","n":"12.1","v":"Perché il catalogo è separato"},{"t":"p","v":"Le rapine disponibili, i requisiti e gli incassi possono cambiare con il wipe. Devono quindi essere mantenuti nell’applicativo o in un allegato aggiornabile, mentre il manuale conserva la procedura di utilizzo."}],"states":["CONFIGURABILE"]},{"num":"13","title":"RAPINA STRUTTURATA","subtitle":"Preparare una scena completa, non soltanto attivare una meccanica.","blocks":[{"t":"table","head":["FASE","ELEMENTI MINIMI"],"rows":[["Obiettivo","Bersaglio, risultato e motivazione narrativa"],["Intelligence","Sopralluogo, informazioni e rischi"],["Squadra","Coordinatore, interni, autista, copertura, recupero"],["Mezzi","Veicolo principale, cambio mezzo, piano alternativo"],["Ticket","Autorizzazioni per oggetti o mezzi speciali"],["Polizia","Negoziazione e possibilità reale di interazione"],["Chiusura","Fuga, arresto, conseguenze e debriefing"]]},{"t":"note","label":"QUALITÀ PRIMA DELLA QUANTITÀ","v":"Una rapina ben preparata può valere più di molte rapine ripetitive. La frequenza non deve trasformare l’attività in farming, ridurre il contenuto o sovraccaricare la polizia."}],"states":[]},{"num":"14","title":"OPERAZIONI COMPLESSE E TICKET","subtitle":"La richiesta deve spiegare cosa serve, perché serve e come sarà usato.","blocks":[{"t":"table","head":["CAMPO DEL TICKET","CONTENUTO"],"rows":[["Motivazione RP","Fatti e sviluppo narrativo"],["Obiettivo","Risultato ricercato"],["Partecipanti","Ruoli e responsabilità"],["Data e orario","Finestra prevista"],["Risorse speciali","Aerei, elicotteri, mezzi marittimi, oggetti o ambienti"],["Modalità d’uso","Durata, limiti e rischio"],["Prove","Video, screenshot o informazioni ottenute in RP"],["Piano alternativo","Cosa accade se la richiesta è limitata o negata"]]},{"t":"p","v":"L’approvazione del ticket rende accessibile uno strumento o una scena; non garantisce il successo e non sostituisce la preparazione operativa."}],"states":[]},{"num":"15","title":"RAPIMENTI","subtitle":"Motivazione, ingaggio, luogo e condizione di chiusura.","blocks":[{"t":"table","head":["ELEMENTO","DECISIONE NECESSARIA","STATO"],"rows":[["Ticket","Quando è richiesto e chi lo apre","VERIFICA STAFF"],["Bersaglio","Perché quella persona è rilevante","DA RATIFICARE"],["Ingaggio","Modalità lecite e coerenti con il server","VERIFICA STAFF"],["Trasporto","Mezzo, percorso e sicurezza","OPERATIVO"],["Luogo","Area autorizzata e controllabile","VERIFICA STAFF"],["Finalità","Informazione, scambio, pressione o sviluppo narrativo","DA RATIFICARE"],["Chiusura","Rilascio, consegna, fuga o altra conseguenza","VERIFICA STAFF"]]},{"t":"note","label":"REGOLA FONDAMENTALE","v":"Il rapimento non deve esistere per occupare una persona o improvvisare violenza. Deve avere uno scopo RP comprensibile, una durata controllata e una conclusione prevista."}],"states":["DA RATIFICARE","VERIFICA STAFF","OPERATIVO"]},{"num":"16","title":"INTERROGATORI","subtitle":"Una conduzione, informazioni precise e limiti chiari.","blocks":[{"t":"h","n":"16.1","v":"Responsabile unico"},{"t":"p","v":"L’interrogatorio viene condotto da una persona autorizzata e informata sul caso. Gli altri partecipanti intervengono soltanto su richiesta o quando possiedono informazioni realmente utili."},{"t":"table","head":["PRIMA","DURANTE","DOPO"],"rows":[["Definire domande, prove e risultato atteso","Mantenere una conduzione coerente","Verificare attendibilità delle risposte"],["Stabilire tempo e condizione di chiusura","Evitare sovrapposizioni e caos","Registrare informazioni e sviluppi"],["Verificare ticket e limiti staff","Interrompere in caso di problemi","Aprire eventuali nuove attività"]]},{"t":"note","label":"PUNTI DA VERIFICARE CON LO STAFF","v":"Controllo di telefono o inventario, conseguenze permanenti, luoghi utilizzabili, durata e modalità ammesse."}],"states":[]},{"num":"17","title":"CAMPI E PROCESSAMENTO","subtitle":"Squadre, calendario, quantità e sicurezza.","blocks":[{"t":"table","head":["PARAMETRO","CONFIGURAZIONE PILOTA","STATO"],"rows":[["Squadra","Minimo 4 - massimo 7 elementi","DA RATIFICARE"],["Equipaggiamento","Sole armi automatiche per la squadra operativa","VERIFICA STAFF"],["Quantità minima","1.000 pezzi","DA RATIFICARE"],["Obiettivo Cartello","5.000 pezzi per accedere alla condizione vantaggiosa","TEMPORANEO"],["Calendario","Partecipazione programmata di tutti gli effettivi","OPERATIVO"]]},{"t":"h","n":"17.1","v":"Ruoli minimi"},{"t":"ul","v":["Coordinatore","Copertura","Raccolta o lavorazione","Trasporto","Deposito e registrazione"]}],"states":["DA RATIFICARE","VERIFICA STAFF","TEMPORANEO","OPERATIVO"]},{"num":"18","title":"ARMI, MUNIZIONI E APPROVVIGIONAMENTI","subtitle":"Cataloghi variabili, inventario stabile.","blocks":[{"t":"table","head":["PROCESSO","REGOLA"],"rows":[["Acquisto","Fornitore, prezzo, quantità e responsabile devono essere registrati."],["Magazzino","Ogni entrata e uscita modifica la giacenza."],["Assegnazione","Il destinatario conferma la presa in carico."],["Vendita","Listino, minimo, massimo e limite settimanale provengono dal catalogo aggiornato."],["Perdita","Arresto, sequestro o smarrimento devono essere segnalati."],["Inventario","Controllo periodico e riconciliazione delle differenze."]]},{"t":"note","label":"CATALOGO SEPARATO","v":"Nomi dei prodotti, prezzi, sovrapprezzi e limiti di acquisto non devono essere fissati nel corpo del manuale: vanno mantenuti nell’applicativo o in un allegato versionato."}],"states":[]},{"num":"19","title":"ALLEATI E COLLABORATORI ESTERNI","subtitle":"Collaborare senza confondere appartenenza e accessi.","blocks":[{"t":"table","head":["TIPO","PUÒ FARE","NON PUÒ FARE"],"rows":[["Alleato operativo","Partecipare a operazioni concordate","Accedere automaticamente a sedi e cassa"],["Fornitore","Reperire armi, mezzi o materiali","Conoscere accordi non necessari"],["Contatto","Fornire informazioni o opportunità","Rappresentare la Famiglia"],["Partner evento","Collaborare a scene pubbliche","Ricevere accessi riservati"]]},{"t":"p","v":"Ogni collaborazione deve avere un referente interno, un perimetro, una durata e una verifica finale. L’alleato può essere importante senza diventare membro della Famiglia."}],"states":[]},{"num":"20","title":"QUALITÀ RP E RAPPORTO CON LA POLIZIA","subtitle":"Valutare la scena anche dal punto di vista della controparte.","blocks":[{"t":"ul","v":["Evitare inseguimenti identici contro gli stessi agenti e con le stesse vie di fuga.","Alternare negoziazioni, diversivi, cambio mezzo, fuga a piedi e scene senza inseguimento finale.","Offrire alla polizia possibilità reali di interazione e investigazione.","Non confondere conoscenza OOC del giocatore con informazioni del personaggio.","Usare il debriefing per prevenire discussioni ripetute in assistenza."]},{"t":"note","label":"DOMANDA DI QUALITÀ","v":"Questa operazione crea una scena interessante per entrambe le parti oppure ripete una dinamica già prevedibile?"}],"states":[]},{"num":"21","title":"INCIDENTI, VIOLAZIONI E ASSISTENZA","subtitle":"Un referente unico, prove ordinate e nessuna discussione caotica.","blocks":[{"t":"table","head":["FASE","AZIONE"],"rows":[["Protezione scena","Interrompere o adattare soltanto quando necessario"],["Raccolta","Video, screenshot, orari e partecipanti"],["Referente","Una persona apre e segue il ticket"],["Comunicazione","Evitare versioni discordanti e discussioni pubbliche"],["Esito","Registrare la decisione dello staff"],["Correzione","Aggiornare procedura, formazione o catalogo"]]},{"t":"note","label":"DIVIETO OPERATIVO","v":"Non trasformare un problema di gioco in un conflitto personale o in una discussione collettiva priva di ordine."}],"states":["OPERATIVO"]},{"num":"22","title":"DEBRIEFING E MIGLIORAMENTO","subtitle":"Ogni attività importante deve lasciare dati e sviluppi.","blocks":[{"t":"table","head":["AREA","DOMANDE"],"rows":[["Obiettivo","È stato raggiunto? Era realistico?"],["Coordinamento","Ruoli e radio hanno funzionato?"],["Regole","Ticket e limiti erano corretti?"],["Economia","Incassi, costi e perdite sono registrati?"],["Qualità RP","La scena ha creato interazioni e conseguenze?"],["Sviluppo","Quale attività nasce da ciò che è accaduto?"],["Correzione","Cosa cambiamo la prossima volta?"]]},{"t":"p","v":"Il debriefing non serve a cercare colpevoli. Serve a trasformare esperienza, errori e risultati in procedure migliori."}],"states":[]},{"num":"A","title":"SCHEDA OPERAZIONE","subtitle":"Modello essenziale per proposta, pianificazione e chiusura.","blocks":[{"t":"table","head":["CAMPO","COMPILAZIONE"],"rows":[["Codice / titolo",""],["Categoria",""],["Responsabile",""],["Obiettivo",""],["Partecipanti e ruoli",""],["Data / orario",""],["Risorse",""],["Ticket richiesto",""],["Rischi",""],["Piano alternativo",""],["Esito",""],["Incasso / costo",""],["Sviluppi successivi",""]]}],"states":[]},{"num":"B","title":"CHECKLIST RAPINA STRUTTURATA","subtitle":"Controllo prima dell’avvio.","blocks":[{"t":"table","head":["CONTROLLO","OK / NOTE"],"rows":[["Obiettivo e motivazione definiti",""],["Sopralluogo completato",""],["Responsabile e sostituto assegnati",""],["Ruoli della squadra confermati",""],["Mezzi e cambio mezzo disponibili",""],["Vie di fuga e recupero preparati",""],["Ticket approvato, se necessario",""],["Piano con la polizia / negoziazione valutato",""],["Risorse registrate",""],["Debriefing programmato",""]]}],"states":[]},{"num":"C","title":"SCHEDA TICKET","subtitle":"Informazioni da preparare prima della richiesta allo staff.","blocks":[{"t":"table","head":["CAMPO","CONTENUTO"],"rows":[["Motivazione RP",""],["Fatti e prove",""],["Obiettivo della scena",""],["Partecipanti",""],["Data e fascia oraria",""],["Risorsa speciale richiesta",""],["Modalità e durata d’uso",""],["Rischi / limiti proposti",""],["Piano alternativo",""],["Responsabile del ticket",""],["Esito staff",""]]}],"states":[]},{"num":"D","title":"SCHEDA RAPIMENTO E INTERROGATORIO","subtitle":"Scopo, limiti e chiusura.","blocks":[{"t":"table","head":["CAMPO","CONTENUTO"],"rows":[["Bersaglio e rilevanza",""],["Motivazione RP",""],["Informazioni possedute",""],["Ticket / verifica staff",""],["Modalità di ingaggio",""],["Luogo e trasporto",""],["Responsabile interrogatorio",""],["Domande e prove",""],["Durata massima",""],["Condizione di chiusura",""],["Esito e informazioni ottenute",""]]}],"states":[]},{"num":"E","title":"REGISTRO CAMPI E PROCESSAMENTO","subtitle":"Calendario, partecipazione e quantità.","blocks":[{"t":"table","head":["DATA","SQUADRA","RUOLI","QUANTITÀ","DEPOSITO / NOTE"],"rows":[]},{"t":"note","label":"CONTROLLO PERIODICO","v":"Confrontare quantità prodotte, consegne al Cartello, soglie raggiunte e partecipazione degli effettivi."},{"t":"table","head":null,"rows":[["F","REGISTRO ECONOMIA E CARTELLO / Movimenti, accordi e distribuzioni."]]},{"t":"table","head":["DATA","TIPO","PROVENIENZA","IMPORTO / Q.TÀ","DESTINAZIONE","RESPONSABILE"],"rows":[]},{"t":"h","n":"F.1","v":"Controlli di fine periodo"},{"t":"ul","v":["Totale entrate","Totale uscite","Reinvestimenti","Riserva","Distribuzioni","Consegne Cartello","Differenze da chiarire"]}],"states":[]},{"num":"R","title":"RATIFICA E REGISTRO MODIFICHE","subtitle":"Approvazione, revisione e responsabilità.","blocks":[{"t":"table","head":["RUOLO","NOME","DECISIONE","DATA"],"rows":[["Capo","","",""],["Vicecapo","","",""],["Vicecapo","","",""],["Vicecapo","","",""],["Responsabile operativo","","",""]]},{"t":"h","n":"R.1","v":"Registro modifiche"},{"t":"table","head":["VERSIONE","DATA","MODIFICA","RESPONSABILE"],"rows":[["1.0","","Prima emissione",""]]},{"t":"note","label":"ENTRATA IN VIGORE","v":"Il manuale diventa operativo soltanto dopo ratifica. Gli accordi temporanei e le condizioni del Cartello devono essere verificati separatamente dopo ogni incontro."}],"states":[]}]}]